export function buildProductionReadinessLigvlakBoard(
  report: ProductionReadinessReport
): ProductionReadinessLigvlakBoard {
  const releaseBoard = buildProductionReadinessReleaseBoard(report);
  const evidenceBoard = buildProductionReadinessEvidenceBoard(report);
  const continuityBoard = buildProductionReadinessContinuityBoard(report);
  const operationsBoard = buildProductionReadinessOperationsBoard(report);
  const serviceBoard = buildProductionReadinessServiceBoard(report);
  const rustvlakBoard = buildProductionReadinessRustvlakBoard(report);

  const ligvlakCheckStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    rustvlakBoard.rustvlakCheckStep,
    rustvlakBoard.rustvlakStep,
    continuityBoard.keepRunningStep,
    operationsBoard.operationsStep,
  ];
  const ligvlakCheckStep =
    ligvlakCheckStepCandidates.find((step): step is ProductionReadinessValidationStep => Boolean(step)) ?? null;

  const ligvlakStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    operationsBoard.ownershipStep,
    serviceBoard.serviceStep,
    serviceBoard.responseStep,
    continuityBoard.continuityStep,
  ];
  const ligvlakStep =
    ligvlakStepCandidates.find(
      (step): step is ProductionReadinessValidationStep => Boolean(step) && step.key !== ligvlakCheckStep?.key
    ) ?? null;

  const items: ProductionReadinessSignoffItem[] = [
    {
      key: 'ligvlak-rustvlak',
      label: 'Rustvlak',
      tone: rustvlakBoard.tone,
      statusLabel: rustvlakBoard.statusLabel,
      detail: rustvlakBoard.summary,
      route: rustvlakBoard.nextRoute?.route ?? rustvlakBoard.rustvlakCheckStep?.route ?? null,
    },
    {
      key: 'ligvlak-check',
      label: 'Ligvlakcheck',
      tone: ligvlakCheckStep?.tone ?? 'success',
      statusLabel: ligvlakCheckStep?.statusLabel ?? 'Bevestigd',
      detail: ligvlakCheckStep
        ? `${ligvlakCheckStep.label}: ${ligvlakCheckStep.detail}`
        : 'Er staat geen actieve ligvlakcheck meer open.',
      route: ligvlakCheckStep?.route ?? null,
    },
    {
      key: 'ligvlak-step',
      label: 'Patroon als vast ligvlak',
      tone: ligvlakStep?.tone ?? 'success',
      statusLabel: ligvlakStep?.statusLabel ?? 'Geborgd',
      detail: ligvlakStep
        ? `${ligvlakStep.label}: ${ligvlakStep.detail}`
        : 'Er staat geen extra ligvlak- of sturingslaag meer open.',
      route: ligvlakStep?.route ?? null,
    },
    {
      key: 'ligvlak-proof',
      label: 'Bevestigd bewijs',
      tone: evidenceBoard.missingCount === 0 ? 'success' : evidenceBoard.topMissing?.tone ?? 'warning',
      statusLabel: evidenceBoard.missingCount === 0 ? 'Bevestigd' : 'Open bewijs',
      detail:
        evidenceBoard.missingCount === 0
          ? 'Alle bewijsregels zijn bevestigd voor de ligvlaklaag.'
          : `${evidenceBoard.missingCount} bewijsregels staan nog open. Focus op ${evidenceBoard.nextProof?.label ?? 'het eerstvolgende bewijs'}.`,
      route: evidenceBoard.nextProof?.route ?? evidenceBoard.topMissing?.route ?? null,
    },
  ];

  const openItems = items.filter((item) => item.tone !== 'success');
  const ligvlakReady =
    openItems.length === 0 ||
    (rustvlakBoard.rustvlakReady &&
      evidenceBoard.missingCount === 0 &&
      !ligvlakCheckStep &&
      !ligvlakStep);
  const nextOpenItem = openItems[0] ?? null;
  const nextRoute =
    nextOpenItem
      ? {
          key: `ligvlak-${nextOpenItem.key}`,
          label: `Open ${nextOpenItem.label}`,
          detail: nextOpenItem.detail,
          route: nextOpenItem.route,
        }
      : null;

  let statusLabel = 'Ligvlaklaag onder voorwaarden';
  let tone: ProductionReadinessTone = 'warning';

  if (items.some((item) => item.tone === 'danger')) {
    statusLabel = 'Ligvlaklaag geblokkeerd';
    tone = 'danger';
  } else if (ligvlakReady) {
    statusLabel = 'Ligvlaklaag bevestigd';
    tone = 'success';
  }

  return {
    headline: statusLabel,
    summary: ligvlakReady
      ? 'Ligvlaklaag is bevestigd en de cockpit ziet geen open ligvlak-, sturings- of bewijsacties meer.'
      : `${openItems.length} ligvlakpunten staan nog open. Werk eerst ${nextOpenItem?.label ?? 'het eerstvolgende ligvlakpunt'} af.`,
    statusLabel,
    tone,
    progress: report.progress,
    releaseDecision: releaseBoard.decisionLabel,
    ligvlakReady,
    openCount: openItems.length,
    nextRoute,
    ligvlakCheckStep,
    ligvlakStep,
    items,
  };
}

