export function buildProductionReadinessKleurtoonBoard(
  report: ProductionReadinessReport
): ProductionReadinessKleurtoonBoard {
  const releaseBoard = buildProductionReadinessReleaseBoard(report);
  const evidenceBoard = buildProductionReadinessEvidenceBoard(report);
  const continuityBoard = buildProductionReadinessContinuityBoard(report);
  const operationsBoard = buildProductionReadinessOperationsBoard(report);
  const serviceBoard = buildProductionReadinessServiceBoard(report);
  const toonBoard = buildProductionReadinessToonBoard(report);

  const kleurtoonCheckStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    toonBoard.toonCheckStep,
    toonBoard.toonStep,
    continuityBoard.keepRunningStep,
    operationsBoard.operationsStep,
  ];
  const kleurtoonCheckStep =
    kleurtoonCheckStepCandidates.find((step): step is ProductionReadinessValidationStep => Boolean(step)) ?? null;

  const kleurtoonStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    operationsBoard.ownershipStep,
    serviceBoard.serviceStep,
    serviceBoard.responseStep,
    continuityBoard.continuityStep,
  ];
  const kleurtoonStep =
    kleurtoonStepCandidates.find(
      (step): step is ProductionReadinessValidationStep => Boolean(step) && step.key !== kleurtoonCheckStep?.key
    ) ?? null;

  const items: ProductionReadinessSignoffItem[] = [
    {
      key: 'kleurtoon-toon',
      label: 'Toon',
      tone: toonBoard.tone,
      statusLabel: toonBoard.statusLabel,
      detail: toonBoard.summary,
      route: toonBoard.nextRoute?.route ?? toonBoard.toonCheckStep?.route ?? null,
    },
    {
      key: 'kleurtoon-check',
      label: 'Kleurtooncheck',
      tone: kleurtoonCheckStep?.tone ?? 'success',
      statusLabel: kleurtoonCheckStep?.statusLabel ?? 'Bevestigd',
      detail: kleurtoonCheckStep
        ? `${kleurtoonCheckStep.label}: ${kleurtoonCheckStep.detail}`
        : 'Er staat geen actieve kleurtooncheck meer open.',
      route: kleurtoonCheckStep?.route ?? null,
    },
    {
      key: 'kleurtoon-step',
      label: 'Patroon als vaste kleurtoon',
      tone: kleurtoonStep?.tone ?? 'success',
      statusLabel: kleurtoonStep?.statusLabel ?? 'Geborgd',
      detail: kleurtoonStep
        ? `${kleurtoonStep.label}: ${kleurtoonStep.detail}`
        : 'Er staat geen extra kleurtoon- of sturingslaag meer open.',
      route: kleurtoonStep?.route ?? null,
    },
    {
      key: 'kleurtoon-proof',
      label: 'Bevestigd bewijs',
      tone: evidenceBoard.missingCount === 0 ? 'success' : evidenceBoard.topMissing?.tone ?? 'warning',
      statusLabel: evidenceBoard.missingCount === 0 ? 'Bevestigd' : 'Open bewijs',
      detail:
        evidenceBoard.missingCount === 0
          ? 'Alle bewijsregels zijn bevestigd voor de kleurtoonlaag.'
          : `${evidenceBoard.missingCount} bewijsregels staan nog open. Focus op ${evidenceBoard.nextProof?.label ?? 'het eerstvolgende bewijs'}.`,
      route: evidenceBoard.nextProof?.route ?? evidenceBoard.topMissing?.route ?? null,
    },
  ];

  const openItems = items.filter((item) => item.tone !== 'success');
  const kleurtoonReady =
    openItems.length === 0 ||
    (toonBoard.toonReady &&
      evidenceBoard.missingCount === 0 &&
      !kleurtoonCheckStep &&
      !kleurtoonStep);
  const nextOpenItem = openItems[0] ?? null;
  const nextRoute =
    nextOpenItem
      ? {
          key: `kleurtoon-${nextOpenItem.key}`,
          label: `Open ${nextOpenItem.label}`,
          detail: nextOpenItem.detail,
          route: nextOpenItem.route,
        }
      : null;

  let statusLabel = 'Kleurtoonlaag onder voorwaarden';
  let tone: ProductionReadinessTone = 'warning';

  if (items.some((item) => item.tone === 'danger')) {
    statusLabel = 'Kleurtoonlaag geblokkeerd';
    tone = 'danger';
  } else if (kleurtoonReady) {
    statusLabel = 'Kleurtoonlaag bevestigd';
    tone = 'success';
  }

  return {
    headline: statusLabel,
    summary: kleurtoonReady
      ? 'Kleurtoonlaag is bevestigd en de cockpit ziet geen open kleurtoon-, sturings- of bewijsacties meer.'
      : `${openItems.length} kleurtoonpunten staan nog open. Werk eerst ${nextOpenItem?.label ?? 'het eerstvolgende kleurtoonpunt'} af.`,
    statusLabel,
    tone,
    progress: report.progress,
    releaseDecision: releaseBoard.decisionLabel,
    kleurtoonReady,
    openCount: openItems.length,
    nextRoute,
    kleurtoonCheckStep,
    kleurtoonStep,
    items,
  };
}

