export function buildProductionReadinessGloedBoard(
  report: ProductionReadinessReport
): ProductionReadinessGloedBoard {
  const releaseBoard = buildProductionReadinessReleaseBoard(report);
  const evidenceBoard = buildProductionReadinessEvidenceBoard(report);
  const continuityBoard = buildProductionReadinessContinuityBoard(report);
  const operationsBoard = buildProductionReadinessOperationsBoard(report);
  const serviceBoard = buildProductionReadinessServiceBoard(report);
  const schijnselBoard = buildProductionReadinessSchijnselBoard(report);

  const gloedCheckStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    schijnselBoard.schijnselCheckStep,
    schijnselBoard.schijnselStep,
    continuityBoard.keepRunningStep,
    operationsBoard.operationsStep,
  ];
  const gloedCheckStep =
    gloedCheckStepCandidates.find((step): step is ProductionReadinessValidationStep => Boolean(step)) ?? null;

  const gloedStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    operationsBoard.ownershipStep,
    serviceBoard.serviceStep,
    serviceBoard.responseStep,
    continuityBoard.continuityStep,
  ];
  const gloedStep =
    gloedStepCandidates.find(
      (step): step is ProductionReadinessValidationStep => Boolean(step) && step.key !== gloedCheckStep?.key
    ) ?? null;

  const items: ProductionReadinessSignoffItem[] = [
    {
      key: 'gloed-schijnsel',
      label: 'Schijnsel',
      tone: schijnselBoard.tone,
      statusLabel: schijnselBoard.statusLabel,
      detail: schijnselBoard.summary,
      route: schijnselBoard.nextRoute?.route ?? schijnselBoard.schijnselCheckStep?.route ?? null,
    },
    {
      key: 'gloed-check',
      label: 'Gloedcheck',
      tone: gloedCheckStep?.tone ?? 'success',
      statusLabel: gloedCheckStep?.statusLabel ?? 'Bevestigd',
      detail: gloedCheckStep
        ? `${gloedCheckStep.label}: ${gloedCheckStep.detail}`
        : 'Er staat geen actieve gloedcheck meer open.',
      route: gloedCheckStep?.route ?? null,
    },
    {
      key: 'gloed-step',
      label: 'Patroon als vaste gloed',
      tone: gloedStep?.tone ?? 'success',
      statusLabel: gloedStep?.statusLabel ?? 'Geborgd',
      detail: gloedStep
        ? `${gloedStep.label}: ${gloedStep.detail}`
        : 'Er staat geen extra gloed- of sturingslaag meer open.',
      route: gloedStep?.route ?? null,
    },
    {
      key: 'gloed-proof',
      label: 'Bevestigd bewijs',
      tone: evidenceBoard.missingCount === 0 ? 'success' : evidenceBoard.topMissing?.tone ?? 'warning',
      statusLabel: evidenceBoard.missingCount === 0 ? 'Bevestigd' : 'Open bewijs',
      detail:
        evidenceBoard.missingCount === 0
          ? 'Alle bewijsregels zijn bevestigd voor de gloedlaag.'
          : `${evidenceBoard.missingCount} bewijsregels staan nog open. Focus op ${evidenceBoard.nextProof?.label ?? 'het eerstvolgende bewijs'}.`,
      route: evidenceBoard.nextProof?.route ?? evidenceBoard.topMissing?.route ?? null,
    },
  ];

  const openItems = items.filter((item) => item.tone !== 'success');
  const gloedReady =
    openItems.length === 0 ||
    (schijnselBoard.schijnselReady &&
      evidenceBoard.missingCount === 0 &&
      !gloedCheckStep &&
      !gloedStep);
  const nextOpenItem = openItems[0] ?? null;
  const nextRoute =
    nextOpenItem
      ? {
          key: `gloed-${nextOpenItem.key}`,
          label: `Open ${nextOpenItem.label}`,
          detail: nextOpenItem.detail,
          route: nextOpenItem.route,
        }
      : null;

  let statusLabel = 'Gloedlaag onder voorwaarden';
  let tone: ProductionReadinessTone = 'warning';

  if (items.some((item) => item.tone === 'danger')) {
    statusLabel = 'Gloedlaag geblokkeerd';
    tone = 'danger';
  } else if (gloedReady) {
    statusLabel = 'Gloedlaag bevestigd';
    tone = 'success';
  }

  return {
    headline: statusLabel,
    summary: gloedReady
      ? 'Gloedlaag is bevestigd en de cockpit ziet geen open gloed-, sturings- of bewijsacties meer.'
      : `${openItems.length} gloedpunten staan nog open. Werk eerst ${nextOpenItem?.label ?? 'het eerstvolgende gloedpunt'} af.`,
    statusLabel,
    tone,
    progress: report.progress,
    releaseDecision: releaseBoard.decisionLabel,
    gloedReady,
    openCount: openItems.length,
    nextRoute,
    gloedCheckStep,
    gloedStep,
    items,
  };
}

