export function buildProductionReadinessBochtBoard(
  report: ProductionReadinessReport
): ProductionReadinessBochtBoard {
  const releaseBoard = buildProductionReadinessReleaseBoard(report);
  const evidenceBoard = buildProductionReadinessEvidenceBoard(report);
  const continuityBoard = buildProductionReadinessContinuityBoard(report);
  const operationsBoard = buildProductionReadinessOperationsBoard(report);
  const serviceBoard = buildProductionReadinessServiceBoard(report);
  const boogBoard = buildProductionReadinessBoogBoard(report);

  const bochtCheckStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    boogBoard.boogCheckStep,
    boogBoard.boogStep,
    continuityBoard.keepRunningStep,
    operationsBoard.operationsStep,
  ];
  const bochtCheckStep =
    bochtCheckStepCandidates.find((step): step is ProductionReadinessValidationStep => Boolean(step)) ?? null;

  const bochtStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    operationsBoard.ownershipStep,
    serviceBoard.serviceStep,
    serviceBoard.responseStep,
    continuityBoard.continuityStep,
  ];
  const bochtStep =
    bochtStepCandidates.find(
      (step): step is ProductionReadinessValidationStep => Boolean(step) && step.key !== bochtCheckStep?.key
    ) ?? null;

  const items: ProductionReadinessSignoffItem[] = [
    {
      key: 'bocht-boog',
      label: 'Boog',
      tone: boogBoard.tone,
      statusLabel: boogBoard.statusLabel,
      detail: boogBoard.summary,
      route: boogBoard.nextRoute?.route ?? boogBoard.boogCheckStep?.route ?? null,
    },
    {
      key: 'bocht-check',
      label: 'Bochtcheck',
      tone: bochtCheckStep?.tone ?? 'success',
      statusLabel: bochtCheckStep?.statusLabel ?? 'Bevestigd',
      detail: bochtCheckStep
        ? `${bochtCheckStep.label}: ${bochtCheckStep.detail}`
        : 'Er staat geen actieve bochtcheck meer open.',
      route: bochtCheckStep?.route ?? null,
    },
    {
      key: 'bocht-step',
      label: 'Patroon als vaste bocht',
      tone: bochtStep?.tone ?? 'success',
      statusLabel: bochtStep?.statusLabel ?? 'Geborgd',
      detail: bochtStep
        ? `${bochtStep.label}: ${bochtStep.detail}`
        : 'Er staat geen extra bocht- of sturingslaag meer open.',
      route: bochtStep?.route ?? null,
    },
    {
      key: 'bocht-proof',
      label: 'Bevestigd bewijs',
      tone: evidenceBoard.missingCount === 0 ? 'success' : evidenceBoard.topMissing?.tone ?? 'warning',
      statusLabel: evidenceBoard.missingCount === 0 ? 'Bevestigd' : 'Open bewijs',
      detail:
        evidenceBoard.missingCount === 0
          ? 'Alle bewijsregels zijn bevestigd voor de bochtlaag.'
          : `${evidenceBoard.missingCount} bewijsregels staan nog open. Focus op ${evidenceBoard.nextProof?.label ?? 'het eerstvolgende bewijs'}.`,
      route: evidenceBoard.nextProof?.route ?? evidenceBoard.topMissing?.route ?? null,
    },
  ];

  const openItems = items.filter((item) => item.tone !== 'success');
  const bochtReady =
    openItems.length === 0 ||
    (boogBoard.boogReady &&
      evidenceBoard.missingCount === 0 &&
      !bochtCheckStep &&
      !bochtStep);
  const nextOpenItem = openItems[0] ?? null;
  const nextRoute =
    nextOpenItem
      ? {
          key: `bocht-${nextOpenItem.key}`,
          label: `Open ${nextOpenItem.label}`,
          detail: nextOpenItem.detail,
          route: nextOpenItem.route,
        }
      : null;

  let statusLabel = 'Bochtlaag onder voorwaarden';
  let tone: ProductionReadinessTone = 'warning';

  if (items.some((item) => item.tone === 'danger')) {
    statusLabel = 'Bochtlaag geblokkeerd';
    tone = 'danger';
  } else if (bochtReady) {
    statusLabel = 'Bochtlaag bevestigd';
    tone = 'success';
  }

  return {
    headline: statusLabel,
    summary: bochtReady
      ? 'Bochtlaag is bevestigd en de cockpit ziet geen open bocht-, sturings- of bewijsacties meer.'
      : `${openItems.length} bochtpunten staan nog open. Werk eerst ${nextOpenItem?.label ?? 'het eerstvolgende bochtpunt'} af.`,
    statusLabel,
    tone,
    progress: report.progress,
    releaseDecision: releaseBoard.decisionLabel,
    bochtReady,
    openCount: openItems.length,
    nextRoute,
    bochtCheckStep,
    bochtStep,
    items,
  };
}

