export function buildProductionReadinessDeiningBoard(
  report: ProductionReadinessReport
): ProductionReadinessDeiningBoard {
  const releaseBoard = buildProductionReadinessReleaseBoard(report);
  const evidenceBoard = buildProductionReadinessEvidenceBoard(report);
  const continuityBoard = buildProductionReadinessContinuityBoard(report);
  const operationsBoard = buildProductionReadinessOperationsBoard(report);
  const serviceBoard = buildProductionReadinessServiceBoard(report);
  const golfslagBoard = buildProductionReadinessGolfslagBoard(report);

  const deiningCheckStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    golfslagBoard.golfslagCheckStep,
    golfslagBoard.golfslagStep,
    continuityBoard.keepRunningStep,
    operationsBoard.operationsStep,
  ];
  const deiningCheckStep =
    deiningCheckStepCandidates.find((step): step is ProductionReadinessValidationStep => Boolean(step)) ?? null;

  const deiningStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    operationsBoard.ownershipStep,
    serviceBoard.serviceStep,
    serviceBoard.responseStep,
    continuityBoard.continuityStep,
  ];
  const deiningStep =
    deiningStepCandidates.find(
      (step): step is ProductionReadinessValidationStep => Boolean(step) && step.key !== deiningCheckStep?.key
    ) ?? null;

  const items: ProductionReadinessSignoffItem[] = [
    {
      key: 'deining-golfslag',
      label: 'Golfslag',
      tone: golfslagBoard.tone,
      statusLabel: golfslagBoard.statusLabel,
      detail: golfslagBoard.summary,
      route: golfslagBoard.nextRoute?.route ?? golfslagBoard.golfslagCheckStep?.route ?? null,
    },
    {
      key: 'deining-check',
      label: 'Deiningcheck',
      tone: deiningCheckStep?.tone ?? 'success',
      statusLabel: deiningCheckStep?.statusLabel ?? 'Bevestigd',
      detail: deiningCheckStep
        ? `${deiningCheckStep.label}: ${deiningCheckStep.detail}`
        : 'Er staat geen actieve deiningcheck meer open.',
      route: deiningCheckStep?.route ?? null,
    },
    {
      key: 'deining-step',
      label: 'Patroon als vaste deining',
      tone: deiningStep?.tone ?? 'success',
      statusLabel: deiningStep?.statusLabel ?? 'Geborgd',
      detail: deiningStep
        ? `${deiningStep.label}: ${deiningStep.detail}`
        : 'Er staat geen extra deining- of sturingslaag meer open.',
      route: deiningStep?.route ?? null,
    },
    {
      key: 'deining-proof',
      label: 'Bevestigd bewijs',
      tone: evidenceBoard.missingCount === 0 ? 'success' : evidenceBoard.topMissing?.tone ?? 'warning',
      statusLabel: evidenceBoard.missingCount === 0 ? 'Bevestigd' : 'Open bewijs',
      detail:
        evidenceBoard.missingCount === 0
          ? 'Alle bewijsregels zijn bevestigd voor de deiningslaag.'
          : `${evidenceBoard.missingCount} bewijsregels staan nog open. Focus op ${evidenceBoard.nextProof?.label ?? 'het eerstvolgende bewijs'}.`,
      route: evidenceBoard.nextProof?.route ?? evidenceBoard.topMissing?.route ?? null,
    },
  ];

  const openItems = items.filter((item) => item.tone !== 'success');
  const deiningReady =
    openItems.length === 0 ||
    (golfslagBoard.golfslagReady &&
      evidenceBoard.missingCount === 0 &&
      !deiningCheckStep &&
      !deiningStep);
  const nextOpenItem = openItems[0] ?? null;
  const nextRoute =
    nextOpenItem
      ? {
          key: `deining-${nextOpenItem.key}`,
          label: `Open ${nextOpenItem.label}`,
          detail: nextOpenItem.detail,
          route: nextOpenItem.route,
        }
      : null;

  let statusLabel = 'Deiningslaag onder voorwaarden';
  let tone: ProductionReadinessTone = 'warning';

  if (items.some((item) => item.tone === 'danger')) {
    statusLabel = 'Deiningslaag geblokkeerd';
    tone = 'danger';
  } else if (deiningReady) {
    statusLabel = 'Deiningslaag bevestigd';
    tone = 'success';
  }

  return {
    headline: statusLabel,
    summary: deiningReady
      ? 'Deiningslaag is bevestigd en de cockpit ziet geen open deining-, sturings- of bewijsacties meer.'
      : `${openItems.length} deiningpunten staan nog open. Werk eerst ${nextOpenItem?.label ?? 'het eerstvolgende deiningpunt'} af.`,
    statusLabel,
    tone,
    progress: report.progress,
    releaseDecision: releaseBoard.decisionLabel,
    deiningReady,
    openCount: openItems.length,
    nextRoute,
    deiningCheckStep,
    deiningStep,
    items,
  };
}

