export function buildProductionReadinessNevelBoard(
  report: ProductionReadinessReport
): ProductionReadinessNevelBoard {
  const releaseBoard = buildProductionReadinessReleaseBoard(report);
  const evidenceBoard = buildProductionReadinessEvidenceBoard(report);
  const continuityBoard = buildProductionReadinessContinuityBoard(report);
  const operationsBoard = buildProductionReadinessOperationsBoard(report);
  const serviceBoard = buildProductionReadinessServiceBoard(report);
  const schuimrandBoard = buildProductionReadinessSchuimrandBoard(report);

  const nevelCheckStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    schuimrandBoard.schuimrandCheckStep,
    schuimrandBoard.schuimrandStep,
    continuityBoard.keepRunningStep,
    operationsBoard.operationsStep,
  ];
  const nevelCheckStep =
    nevelCheckStepCandidates.find((step): step is ProductionReadinessValidationStep => Boolean(step)) ?? null;

  const nevelStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    operationsBoard.ownershipStep,
    serviceBoard.serviceStep,
    serviceBoard.responseStep,
    continuityBoard.continuityStep,
  ];
  const nevelStep =
    nevelStepCandidates.find(
      (step): step is ProductionReadinessValidationStep => Boolean(step) && step.key !== nevelCheckStep?.key
    ) ?? null;

  const items: ProductionReadinessSignoffItem[] = [
    {
      key: 'nevel-schuimrand',
      label: 'Schuimrand',
      tone: schuimrandBoard.tone,
      statusLabel: schuimrandBoard.statusLabel,
      detail: schuimrandBoard.summary,
      route: schuimrandBoard.nextRoute?.route ?? schuimrandBoard.schuimrandCheckStep?.route ?? null,
    },
    {
      key: 'nevel-check',
      label: 'Nevelcheck',
      tone: nevelCheckStep?.tone ?? 'success',
      statusLabel: nevelCheckStep?.statusLabel ?? 'Bevestigd',
      detail: nevelCheckStep
        ? `${nevelCheckStep.label}: ${nevelCheckStep.detail}`
        : 'Er staat geen actieve nevelcheck meer open.',
      route: nevelCheckStep?.route ?? null,
    },
    {
      key: 'nevel-step',
      label: 'Patroon als vaste nevel',
      tone: nevelStep?.tone ?? 'success',
      statusLabel: nevelStep?.statusLabel ?? 'Geborgd',
      detail: nevelStep
        ? `${nevelStep.label}: ${nevelStep.detail}`
        : 'Er staat geen extra nevel- of sturingslaag meer open.',
      route: nevelStep?.route ?? null,
    },
    {
      key: 'nevel-proof',
      label: 'Bevestigd bewijs',
      tone: evidenceBoard.missingCount === 0 ? 'success' : evidenceBoard.topMissing?.tone ?? 'warning',
      statusLabel: evidenceBoard.missingCount === 0 ? 'Bevestigd' : 'Open bewijs',
      detail:
        evidenceBoard.missingCount === 0
          ? 'Alle bewijsregels zijn bevestigd voor de nevellaag.'
          : `${evidenceBoard.missingCount} bewijsregels staan nog open. Focus op ${evidenceBoard.nextProof?.label ?? 'het eerstvolgende bewijs'}.`,
      route: evidenceBoard.nextProof?.route ?? evidenceBoard.topMissing?.route ?? null,
    },
  ];

  const openItems = items.filter((item) => item.tone !== 'success');
  const nevelReady =
    openItems.length === 0 ||
    (schuimrandBoard.schuimrandReady &&
      evidenceBoard.missingCount === 0 &&
      !nevelCheckStep &&
      !nevelStep);
  const nextOpenItem = openItems[0] ?? null;
  const nextRoute =
    nextOpenItem
      ? {
          key: `nevel-${nextOpenItem.key}`,
          label: `Open ${nextOpenItem.label}`,
          detail: nextOpenItem.detail,
          route: nextOpenItem.route,
        }
      : null;

  let statusLabel = 'Nevellaag onder voorwaarden';
  let tone: ProductionReadinessTone = 'warning';

  if (items.some((item) => item.tone === 'danger')) {
    statusLabel = 'Nevellaag geblokkeerd';
    tone = 'danger';
  } else if (nevelReady) {
    statusLabel = 'Nevellaag bevestigd';
    tone = 'success';
  }

  return {
    headline: statusLabel,
    summary: nevelReady
      ? 'Nevellaag is bevestigd en de cockpit ziet geen open nevel-, sturings- of bewijsacties meer.'
      : `${openItems.length} nevelpunten staan nog open. Werk eerst ${nextOpenItem?.label ?? 'het eerstvolgende nevelpunt'} af.`,
    statusLabel,
    tone,
    progress: report.progress,
    releaseDecision: releaseBoard.decisionLabel,
    nevelReady,
    openCount: openItems.length,
    nextRoute,
    nevelCheckStep,
    nevelStep,
    items,
  };
}

