export function buildProductionReadinessKleurwaasBoard(
  report: ProductionReadinessReport
): ProductionReadinessKleurwaasBoard {
  const releaseBoard = buildProductionReadinessReleaseBoard(report);
  const evidenceBoard = buildProductionReadinessEvidenceBoard(report);
  const continuityBoard = buildProductionReadinessContinuityBoard(report);
  const operationsBoard = buildProductionReadinessOperationsBoard(report);
  const serviceBoard = buildProductionReadinessServiceBoard(report);
  const tintsluierBoard = buildProductionReadinessTintsluierBoard(report);

  const kleurwaasCheckStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    tintsluierBoard.tintsluierCheckStep,
    tintsluierBoard.tintsluierStep,
    continuityBoard.keepRunningStep,
    operationsBoard.operationsStep,
  ];
  const kleurwaasCheckStep =
    kleurwaasCheckStepCandidates.find((step): step is ProductionReadinessValidationStep => Boolean(step)) ?? null;

  const kleurwaasStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    operationsBoard.ownershipStep,
    serviceBoard.serviceStep,
    serviceBoard.responseStep,
    continuityBoard.continuityStep,
  ];
  const kleurwaasStep =
    kleurwaasStepCandidates.find(
      (step): step is ProductionReadinessValidationStep => Boolean(step) && step.key !== kleurwaasCheckStep?.key
    ) ?? null;

  const items: ProductionReadinessSignoffItem[] = [
    {
      key: 'kleurwaas-tintsluier',
      label: 'Tintsluier',
      tone: tintsluierBoard.tone,
      statusLabel: tintsluierBoard.statusLabel,
      detail: tintsluierBoard.summary,
      route: tintsluierBoard.nextRoute?.route ?? tintsluierBoard.tintsluierCheckStep?.route ?? null,
    },
    {
      key: 'kleurwaas-check',
      label: 'Kleurwaascheck',
      tone: kleurwaasCheckStep?.tone ?? 'success',
      statusLabel: kleurwaasCheckStep?.statusLabel ?? 'Bevestigd',
      detail: kleurwaasCheckStep
        ? `${kleurwaasCheckStep.label}: ${kleurwaasCheckStep.detail}`
        : 'Er staat geen actieve kleurwaascheck meer open.',
      route: kleurwaasCheckStep?.route ?? null,
    },
    {
      key: 'kleurwaas-step',
      label: 'Patroon als vaste kleurwaas',
      tone: kleurwaasStep?.tone ?? 'success',
      statusLabel: kleurwaasStep?.statusLabel ?? 'Geborgd',
      detail: kleurwaasStep
        ? `${kleurwaasStep.label}: ${kleurwaasStep.detail}`
        : 'Er staat geen extra kleurwaas- of sturingslaag meer open.',
      route: kleurwaasStep?.route ?? null,
    },
    {
      key: 'kleurwaas-proof',
      label: 'Bevestigd bewijs',
      tone: evidenceBoard.missingCount === 0 ? 'success' : evidenceBoard.topMissing?.tone ?? 'warning',
      statusLabel: evidenceBoard.missingCount === 0 ? 'Bevestigd' : 'Open bewijs',
      detail:
        evidenceBoard.missingCount === 0
          ? 'Alle bewijsregels zijn bevestigd voor de kleurwaaslaag.'
          : `${evidenceBoard.missingCount} bewijsregels staan nog open. Focus op ${evidenceBoard.nextProof?.label ?? 'het eerstvolgende bewijs'}.`,
      route: evidenceBoard.nextProof?.route ?? evidenceBoard.topMissing?.route ?? null,
    },
  ];

  const openItems = items.filter((item) => item.tone !== 'success');
  const kleurwaasReady =
    openItems.length === 0 ||
    (tintsluierBoard.tintsluierReady &&
      evidenceBoard.missingCount === 0 &&
      !kleurwaasCheckStep &&
      !kleurwaasStep);
  const nextOpenItem = openItems[0] ?? null;
  const nextRoute =
    nextOpenItem
      ? {
          key: `kleurwaas-${nextOpenItem.key}`,
          label: `Open ${nextOpenItem.label}`,
          detail: nextOpenItem.detail,
          route: nextOpenItem.route,
        }
      : null;

  let statusLabel = 'Kleurwaaslaag onder voorwaarden';
  let tone: ProductionReadinessTone = 'warning';

  if (items.some((item) => item.tone === 'danger')) {
    statusLabel = 'Kleurwaaslaag geblokkeerd';
    tone = 'danger';
  } else if (kleurwaasReady) {
    statusLabel = 'Kleurwaaslaag bevestigd';
    tone = 'success';
  }

  return {
    headline: statusLabel,
    summary: kleurwaasReady
      ? 'Kleurwaaslaag is bevestigd en de cockpit ziet geen open kleurwaas-, sturings- of bewijsacties meer.'
      : `${openItems.length} kleurwaaspunten staan nog open. Werk eerst ${nextOpenItem?.label ?? 'het eerstvolgende kleurwaaspunt'} af.`,
    statusLabel,
    tone,
    progress: report.progress,
    releaseDecision: releaseBoard.decisionLabel,
    kleurwaasReady,
    openCount: openItems.length,
    nextRoute,
    kleurwaasCheckStep,
    kleurwaasStep,
    items,
  };
}

