export function buildProductionReadinessKleurfilmBoard(
  report: ProductionReadinessReport
): ProductionReadinessKleurfilmBoard {
  const releaseBoard = buildProductionReadinessReleaseBoard(report);
  const evidenceBoard = buildProductionReadinessEvidenceBoard(report);
  const continuityBoard = buildProductionReadinessContinuityBoard(report);
  const operationsBoard = buildProductionReadinessOperationsBoard(report);
  const serviceBoard = buildProductionReadinessServiceBoard(report);
  const tintfloersBoard = buildProductionReadinessTintfloersBoard(report);

  const kleurfilmCheckStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    tintfloersBoard.tintfloersCheckStep,
    tintfloersBoard.tintfloersStep,
    continuityBoard.keepRunningStep,
    operationsBoard.operationsStep,
  ];
  const kleurfilmCheckStep =
    kleurfilmCheckStepCandidates.find((step): step is ProductionReadinessValidationStep => Boolean(step)) ?? null;

  const kleurfilmStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    operationsBoard.ownershipStep,
    serviceBoard.serviceStep,
    serviceBoard.responseStep,
    continuityBoard.continuityStep,
  ];
  const kleurfilmStep =
    kleurfilmStepCandidates.find(
      (step): step is ProductionReadinessValidationStep => Boolean(step) && step.key !== kleurfilmCheckStep?.key
    ) ?? null;

  const items: ProductionReadinessSignoffItem[] = [
    {
      key: 'kleurfilm-tintfloers',
      label: 'Tintfloers',
      tone: tintfloersBoard.tone,
      statusLabel: tintfloersBoard.statusLabel,
      detail: tintfloersBoard.summary,
      route: tintfloersBoard.nextRoute?.route ?? tintfloersBoard.tintfloersCheckStep?.route ?? null,
    },
    {
      key: 'kleurfilm-check',
      label: 'Kleurfilmcheck',
      tone: kleurfilmCheckStep?.tone ?? 'success',
      statusLabel: kleurfilmCheckStep?.statusLabel ?? 'Bevestigd',
      detail: kleurfilmCheckStep
        ? `${kleurfilmCheckStep.label}: ${kleurfilmCheckStep.detail}`
        : 'Er staat geen actieve kleurfilmcheck meer open.',
      route: kleurfilmCheckStep?.route ?? null,
    },
    {
      key: 'kleurfilm-step',
      label: 'Patroon als vaste kleurfilm',
      tone: kleurfilmStep?.tone ?? 'success',
      statusLabel: kleurfilmStep?.statusLabel ?? 'Geborgd',
      detail: kleurfilmStep
        ? `${kleurfilmStep.label}: ${kleurfilmStep.detail}`
        : 'Er staat geen extra kleurfilm- of sturingslaag meer open.',
      route: kleurfilmStep?.route ?? null,
    },
    {
      key: 'kleurfilm-proof',
      label: 'Bevestigd bewijs',
      tone: evidenceBoard.missingCount === 0 ? 'success' : evidenceBoard.topMissing?.tone ?? 'warning',
      statusLabel: evidenceBoard.missingCount === 0 ? 'Bevestigd' : 'Open bewijs',
      detail:
        evidenceBoard.missingCount === 0
          ? 'Alle bewijsregels zijn bevestigd voor de kleurfilmlaag.'
          : `${evidenceBoard.missingCount} bewijsregels staan nog open. Focus op ${evidenceBoard.nextProof?.label ?? 'het eerstvolgende bewijs'}.`,
      route: evidenceBoard.nextProof?.route ?? evidenceBoard.topMissing?.route ?? null,
    },
  ];

  const openItems = items.filter((item) => item.tone !== 'success');
  const kleurfilmReady =
    openItems.length === 0 ||
    (tintfloersBoard.tintfloersReady &&
      evidenceBoard.missingCount === 0 &&
      !kleurfilmCheckStep &&
      !kleurfilmStep);
  const nextOpenItem = openItems[0] ?? null;
  const nextRoute =
    nextOpenItem
      ? {
          key: `kleurfilm-${nextOpenItem.key}`,
          label: `Open ${nextOpenItem.label}`,
          detail: nextOpenItem.detail,
          route: nextOpenItem.route,
        }
      : null;

  let statusLabel = 'Kleurfilmlaag onder voorwaarden';
  let tone: ProductionReadinessTone = 'warning';

  if (items.some((item) => item.tone === 'danger')) {
    statusLabel = 'Kleurfilmlaag geblokkeerd';
    tone = 'danger';
  } else if (kleurfilmReady) {
    statusLabel = 'Kleurfilmlaag bevestigd';
    tone = 'success';
  }

  return {
    headline: statusLabel,
    summary: kleurfilmReady
      ? 'Kleurfilmlaag is bevestigd en de cockpit ziet geen open kleurfilm-, sturings- of bewijsacties meer.'
      : `${openItems.length} kleurfilmpunten staan nog open. Werk eerst ${nextOpenItem?.label ?? 'het eerstvolgende kleurfilmpunt'} af.`,
    statusLabel,
    tone,
    progress: report.progress,
    releaseDecision: releaseBoard.decisionLabel,
    kleurfilmReady,
    openCount: openItems.length,
    nextRoute,
    kleurfilmCheckStep,
    kleurfilmStep,
    items,
  };
}

