export function buildProductionReadinessTintstrookBoard(
  report: ProductionReadinessReport
): ProductionReadinessTintstrookBoard {
  const releaseBoard = buildProductionReadinessReleaseBoard(report);
  const evidenceBoard = buildProductionReadinessEvidenceBoard(report);
  const continuityBoard = buildProductionReadinessContinuityBoard(report);
  const operationsBoard = buildProductionReadinessOperationsBoard(report);
  const serviceBoard = buildProductionReadinessServiceBoard(report);
  const kleurstrookBoard = buildProductionReadinessKleurstrookBoard(report);

  const tintstrookCheckStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    kleurstrookBoard.kleurstrookCheckStep,
    kleurstrookBoard.kleurstrookStep,
    continuityBoard.keepRunningStep,
    operationsBoard.operationsStep,
  ];
  const tintstrookCheckStep =
    tintstrookCheckStepCandidates.find((step): step is ProductionReadinessValidationStep => Boolean(step)) ?? null;

  const tintstrookStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    operationsBoard.ownershipStep,
    serviceBoard.serviceStep,
    serviceBoard.responseStep,
    continuityBoard.continuityStep,
  ];
  const tintstrookStep =
    tintstrookStepCandidates.find(
      (step): step is ProductionReadinessValidationStep => Boolean(step) && step.key !== tintstrookCheckStep?.key
    ) ?? null;

  const items: ProductionReadinessSignoffItem[] = [
    {
      key: 'tintstrook-kleurstrook',
      label: 'Kleurstrook',
      tone: kleurstrookBoard.tone,
      statusLabel: kleurstrookBoard.statusLabel,
      detail: kleurstrookBoard.summary,
      route: kleurstrookBoard.nextRoute?.route ?? kleurstrookBoard.kleurstrookCheckStep?.route ?? null,
    },
    {
      key: 'tintstrook-check',
      label: 'Tintstrookcheck',
      tone: tintstrookCheckStep?.tone ?? 'success',
      statusLabel: tintstrookCheckStep?.statusLabel ?? 'Bevestigd',
      detail: tintstrookCheckStep
        ? `${tintstrookCheckStep.label}: ${tintstrookCheckStep.detail}`
        : 'Er staat geen actieve tintstrookcheck meer open.',
      route: tintstrookCheckStep?.route ?? null,
    },
    {
      key: 'tintstrook-step',
      label: 'Patroon als vaste tintstrook',
      tone: tintstrookStep?.tone ?? 'success',
      statusLabel: tintstrookStep?.statusLabel ?? 'Geborgd',
      detail: tintstrookStep
        ? `${tintstrookStep.label}: ${tintstrookStep.detail}`
        : 'Er staat geen extra tintstrook- of sturingslaag meer open.',
      route: tintstrookStep?.route ?? null,
    },
    {
      key: 'tintstrook-proof',
      label: 'Bevestigd bewijs',
      tone: evidenceBoard.missingCount === 0 ? 'success' : evidenceBoard.topMissing?.tone ?? 'warning',
      statusLabel: evidenceBoard.missingCount === 0 ? 'Bevestigd' : 'Open bewijs',
      detail:
        evidenceBoard.missingCount === 0
          ? 'Alle bewijsregels zijn bevestigd voor de tintstrook.'
          : `${evidenceBoard.missingCount} bewijsregels staan nog open. Focus op ${evidenceBoard.nextProof?.label ?? 'het eerstvolgende bewijs'}.`,
      route: evidenceBoard.nextProof?.route ?? evidenceBoard.topMissing?.route ?? null,
    },
  ];

  const openItems = items.filter((item) => item.tone !== 'success');
  const tintstrookReady =
    openItems.length === 0 ||
    (kleurstrookBoard.kleurstrookReady &&
      evidenceBoard.missingCount === 0 &&
      !tintstrookCheckStep &&
      !tintstrookStep);
  const nextOpenItem = openItems[0] ?? null;
  const nextRoute =
    nextOpenItem
      ? {
          key: `tintstrook-${nextOpenItem.key}`,
          label: `Open ${nextOpenItem.label}`,
          detail: nextOpenItem.detail,
          route: nextOpenItem.route,
        }
      : null;

  let statusLabel = 'Tintstrook onder voorwaarden';
  let tone: ProductionReadinessTone = 'warning';

  if (items.some((item) => item.tone === 'danger')) {
    statusLabel = 'Tintstrook geblokkeerd';
    tone = 'danger';
  } else if (tintstrookReady) {
    statusLabel = 'Tintstrook bevestigd';
    tone = 'success';
  }

  return {
    headline: statusLabel,
    summary: tintstrookReady
      ? 'Tintstrook is bevestigd en de cockpit ziet geen open tintstrook-, sturings- of bewijsacties meer.'
      : `${openItems.length} tintstrookpunten staan nog open. Werk eerst ${nextOpenItem?.label ?? 'het eerstvolgende tintstrookpunt'} af.`,
    statusLabel,
    tone,
    progress: report.progress,
    releaseDecision: releaseBoard.decisionLabel,
    tintstrookReady,
    openCount: openItems.length,
    nextRoute,
    tintstrookCheckStep,
    tintstrookStep,
    items,
  };
}

