export function buildProductionReadinessKleuraderBoard(
  report: ProductionReadinessReport
): ProductionReadinessKleuraderBoard {
  const releaseBoard = buildProductionReadinessReleaseBoard(report);
  const evidenceBoard = buildProductionReadinessEvidenceBoard(report);
  const continuityBoard = buildProductionReadinessContinuityBoard(report);
  const operationsBoard = buildProductionReadinessOperationsBoard(report);
  const serviceBoard = buildProductionReadinessServiceBoard(report);
  const tintkabelBoard = buildProductionReadinessTintkabelBoard(report);

  const kleuraderCheckStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    tintkabelBoard.tintkabelCheckStep,
    tintkabelBoard.tintkabelStep,
    continuityBoard.keepRunningStep,
    operationsBoard.operationsStep,
  ];
  const kleuraderCheckStep =
    kleuraderCheckStepCandidates.find((step): step is ProductionReadinessValidationStep => Boolean(step)) ?? null;

  const kleuraderStepCandidates: Array<ProductionReadinessValidationStep | null> = [
    operationsBoard.ownershipStep,
    serviceBoard.serviceStep,
    serviceBoard.responseStep,
    continuityBoard.continuityStep,
  ];
  const kleuraderStep =
    kleuraderStepCandidates.find(
      (step): step is ProductionReadinessValidationStep => Boolean(step) && step.key !== kleuraderCheckStep?.key
    ) ?? null;

  const items: ProductionReadinessSignoffItem[] = [
    {
      key: 'kleurader-tintkabel',
      label: 'Tintkabel',
      tone: tintkabelBoard.tone,
      statusLabel: tintkabelBoard.statusLabel,
      detail: tintkabelBoard.summary,
      route: tintkabelBoard.nextRoute?.route ?? tintkabelBoard.tintkabelCheckStep?.route ?? null,
    },
    {
      key: 'kleurader-check',
      label: 'Kleuradercheck',
      tone: kleuraderCheckStep?.tone ?? 'success',
      statusLabel: kleuraderCheckStep?.statusLabel ?? 'Bevestigd',
      detail: kleuraderCheckStep
        ? `${kleuraderCheckStep.label}: ${kleuraderCheckStep.detail}`
        : 'Er staat geen actieve kleuradercheck meer open.',
      route: kleuraderCheckStep?.route ?? null,
    },
    {
      key: 'kleurader-step',
      label: 'Patroon als vaste kleurader',
      tone: kleuraderStep?.tone ?? 'success',
      statusLabel: kleuraderStep?.statusLabel ?? 'Geborgd',
      detail: kleuraderStep
        ? `${kleuraderStep.label}: ${kleuraderStep.detail}`
        : 'Er staat geen extra kleurader- of sturingslaag meer open.',
      route: kleuraderStep?.route ?? null,
    },
    {
      key: 'kleurader-proof',
      label: 'Bevestigd bewijs',
      tone: evidenceBoard.missingCount === 0 ? 'success' : evidenceBoard.topMissing?.tone ?? 'warning',
      statusLabel: evidenceBoard.missingCount === 0 ? 'Bevestigd' : 'Open bewijs',
      detail:
        evidenceBoard.missingCount === 0
          ? 'Alle bewijsregels zijn bevestigd voor de kleurader.'
          : `${evidenceBoard.missingCount} bewijsregels staan nog open. Focus op ${evidenceBoard.nextProof?.label ?? 'het eerstvolgende bewijs'}.`,
      route: evidenceBoard.nextProof?.route ?? evidenceBoard.topMissing?.route ?? null,
    },
  ];

  const openItems = items.filter((item) => item.tone !== 'success');
  const kleuraderReady =
    openItems.length === 0 ||
    (tintkabelBoard.tintkabelReady &&
      evidenceBoard.missingCount === 0 &&
      !kleuraderCheckStep &&
      !kleuraderStep);
  const nextOpenItem = openItems[0] ?? null;
  const nextRoute =
    nextOpenItem
      ? {
          key: `kleurader-${nextOpenItem.key}`,
          label: `Open ${nextOpenItem.label}`,
          detail: nextOpenItem.detail,
          route: nextOpenItem.route,
        }
      : null;

  let statusLabel = 'Kleurader onder voorwaarden';
  let tone: ProductionReadinessTone = 'warning';

  if (items.some((item) => item.tone === 'danger')) {
    statusLabel = 'Kleurader geblokkeerd';
    tone = 'danger';
  } else if (kleuraderReady) {
    statusLabel = 'Kleurader bevestigd';
    tone = 'success';
  }

  return {
    headline: statusLabel,
    summary: kleuraderReady
      ? 'Kleurader is bevestigd en de cockpit ziet geen open kleurader-, sturings- of bewijsacties meer.'
      : `${openItems.length} kleuraderpunten staan nog open. Werk eerst ${nextOpenItem?.label ?? 'het eerstvolgende kleuraderpunt'} af.`,
    statusLabel,
    tone,
    progress: report.progress,
    releaseDecision: releaseBoard.decisionLabel,
    kleuraderReady,
    openCount: openItems.length,
    nextRoute,
    kleuraderCheckStep,
    kleuraderStep,
    items,
  };
}

